<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { eliminarDocumentoCompra, guardarDocumentoCompra, listarDocumentosCompra } from '../services/documentosCompra'
import type { DocumentoCompra } from '../interfaces/documentosCompra.interface'
const rows=ref<DocumentoCompra[]>([]),criterio=ref(''),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),editing=ref<number|null>(null)
const form=reactive({codigo:'',denominacion:'',tipo_operacion:0 as 0|1|2,afectacion:'S' as 'S'|'N',cta_prov_moneda_nacional:'',cta_prov_moneda_extranjera:'',detraccion:false,activo:true})
const operationNames:Record<number,string>={0:'Compras en general',1:'Ingreso de almacén',2:'Salida de almacén'}
async function load(next=1){page.value=next;loading.value=true;error.value='';try{const r=await listarDocumentosCompra(criterio.value,next);rows.value=r.data;total.value=r.total;lastPage.value=r.last_page}catch(e){error.value=message(e)}finally{loading.value=false}}
function open(item?:DocumentoCompra){editing.value=item?.id||null;Object.assign(form,{codigo:item?.codigo||'',denominacion:item?.denominacion||'',tipo_operacion:item?.tipo_operacion??0,afectacion:item?.afectacion||'S',cta_prov_moneda_nacional:item?.cta_prov_moneda_nacional||'',cta_prov_moneda_extranjera:item?.cta_prov_moneda_extranjera||'',detraccion:item?.detraccion||false,activo:item?.activo??true});modal.value=true}
function validate(){if(!form.codigo.trim()||form.codigo.length>5)return 'El código es obligatorio y admite hasta 5 caracteres.';if(!form.denominacion.trim())return 'La denominación es obligatoria.';if(!form.cta_prov_moneda_nacional.trim())return 'Ingrese la cuenta del proveedor en moneda nacional.';if(!form.cta_prov_moneda_extranjera.trim())return 'Ingrese la cuenta del proveedor en moneda extranjera.';return ''}
async function save(){const issue=validate();if(issue){error.value=issue;return}saving.value=true;try{await guardarDocumentoCompra(editing.value,{...form});modal.value=false;success.value=`Documento ${editing.value?'actualizado':'creado'} correctamente.`;await load(editing.value?page.value:1)}catch(e){error.value=message(e)}finally{saving.value=false}}
async function remove(item:DocumentoCompra){if(item.movimientos_count){error.value='No se puede eliminar el documento porque tiene movimientos asociados.';return}if(!confirm(`¿Eliminar el documento “${item.denominacion}”?`))return;try{await eliminarDocumentoCompra(item.id);success.value='Documento eliminado correctamente.';await load(page.value)}catch(e){error.value=message(e)}}
const message=(e:unknown)=>e instanceof Error?e.message:'No se pudo completar la operación.';onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Logística / Documentos de compra</nav><header class="hero"><div class="mark">DC</div><div><small>MIA · CONFIGURACIÓN CONTABLE</small><h1>Documentos de compra</h1><p>Configura los comprobantes utilizados en compras y almacén.</p></div><b>{{total}} documentos</b><button @click="open()">+ Agregar documento</button></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash">{{error}}</p><section class="filters"><input v-model.trim="criterio" placeholder="Buscar por código o denominación" @keyup.enter="load(1)"><button @click="load(1)">Buscar</button><button class="soft" @click="criterio='';load(1)">Limpiar</button></section><div v-if="loading" class="empty">Cargando documentos…</div><div v-else-if="!rows.length" class="empty">No se encontraron documentos de compra.</div>
<section v-else class="cards"><article v-for="item in rows" :key="item.id" :class="{inactive:!item.activo}"><header><div class="code">{{item.codigo}}</div><div><small>{{operationNames[item.tipo_operacion]}}</small><h2>{{item.denominacion}}</h2></div><span>{{item.activo?'ACTIVO':'INACTIVO'}}</span></header><dl><div><dt>Afectación</dt><dd>{{item.afectacion==='S'?'Afecto':'No afecto'}}</dd></div><div><dt>Cuenta MN</dt><dd>{{item.cta_prov_moneda_nacional}}</dd></div><div><dt>Cuenta ME</dt><dd>{{item.cta_prov_moneda_extranjera}}</dd></div><div><dt>Detracción</dt><dd>{{item.detraccion?'Sí':'No'}}</dd></div><div><dt>Movimientos asociados</dt><dd>{{item.movimientos_count}}</dd></div></dl><footer><button @click="open(item)">Modificar</button><button class="danger" :disabled="item.movimientos_count>0" @click="remove(item)">Eliminar</button></footer></article></section><footer v-if="lastPage>1" class="pages"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer>
<div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog" @submit.prevent="save"><header><div><small>TIPO DE COMPROBANTE</small><h2>{{editing?'Modificar':'Registrar'}} documento</h2></div><button type="button" @click="modal=false">×</button></header><div class="grid"><label>Código *<input v-model.trim="form.codigo" maxlength="5"></label><label>Tipo de operación *<select v-model.number="form.tipo_operacion"><option :value="0">Compras en general</option><option :value="1">Ingreso de almacén</option><option :value="2">Salida de almacén</option></select></label><label class="wide">Denominación *<input v-model.trim="form.denominacion" maxlength="255"></label><label>Afectación *<select v-model="form.afectacion"><option value="S">Afecto</option><option value="N">No afecto</option></select></label><label>Cuenta proveedor - moneda nacional *<input v-model.trim="form.cta_prov_moneda_nacional" maxlength="20"></label><label>Cuenta proveedor - moneda extranjera *<input v-model.trim="form.cta_prov_moneda_extranjera" maxlength="20"></label></div><section class="checks"><label><input v-model="form.detraccion" type="checkbox"> Sujeto a detracción</label><label><input v-model="form.activo" type="checkbox"> Documento activo</label></section><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':'Guardar documento'}}</button></footer></form></div></div></template>
<style scoped>
.page{--accent:#d64f83;color:#35464e}nav{margin-bottom:16px;color:#929fa5;font-size:.68rem}nav a{color:var(--accent);text-decoration:none}.hero{padding:20px 23px;display:flex;align-items:center;gap:14px;border-left:5px solid var(--accent);border-radius:12px;background:#fff}.mark{width:50px;height:50px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--accent);font-size:.65rem;font-weight:700}.hero small,.cards small,.dialog small{color:var(--accent);font-size:.48rem;font-weight:800}.hero h1{margin:2px 0;font-size:1.3rem}.hero p{margin:0;color:#7e8a90;font-size:.67rem}.hero>b{margin-left:auto;font-size:.55rem}.hero button,.filters button,.pages button,.dialog button{padding:8px 10px;border:0;border-radius:6px;color:#fff;background:var(--accent);font-size:.52rem}.flash{padding:9px;border-radius:7px;color:#a64046;background:#fff0f0;font-size:.6rem}.flash.success{color:#287052;background:#edf9f3}.filters{margin-top:11px;padding:11px;display:flex;gap:6px;border-radius:9px;background:#fff}.filters input{flex:1}.soft{color:#64727a!important;background:#edf1f3!important}input,select{width:100%;box-sizing:border-box;padding:8px;border:1px solid #d9e0e3;border-radius:6px;font:inherit;font-size:.55rem}.empty{margin-top:11px;padding:45px;text-align:center;background:#fff;font-size:.6rem}.cards{margin-top:11px;display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.cards article{padding:13px;border:1px solid #e0e5e7;border-top:4px solid #506f9b;border-radius:9px;background:#fff}.cards article.inactive{opacity:.65;border-top-color:#9da7ac}.cards article>header{display:flex;align-items:center;gap:8px}.code{min-width:36px;height:36px;padding:0 5px;display:grid;place-items:center;border-radius:8px;color:#fff;background:#506f9b;font-size:.55rem;font-weight:700}.cards h2{margin:2px 0;font-size:.68rem}.cards header span{margin-left:auto;padding:4px 6px;border-radius:8px;color:#287154;background:#e7f7ef;font-size:.43rem}.inactive header span{color:#68767d;background:#edf0f2}.cards dl{margin:10px 0}.cards dl div{padding:5px 0;display:flex;border-bottom:1px solid #edf0f1;font-size:.51rem}.cards dt{color:#78858b}.cards dd{margin-left:auto}.cards footer{display:flex}.cards footer button{border:0;color:var(--accent);background:none;font-size:.48rem}.cards footer .danger{margin-left:auto;color:#b53f46}.cards footer button:disabled{color:#adb4b7}.pages{margin-top:12px;display:flex;justify-content:center;align-items:center;gap:8px;font-size:.52rem}.backdrop{position:fixed;z-index:100;inset:0;padding:20px;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(720px,100%);padding:20px;box-sizing:border-box;border-radius:12px;background:#fff}.dialog>header{display:flex}.dialog h2{margin:2px 0 13px;font-size:1rem}.dialog>header button{margin-left:auto;color:#59666c;background:none;font-size:1.2rem}.grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}.wide{grid-column:1/-1}.dialog label{font-size:.51rem}.dialog label input,.dialog label select{margin-top:4px}.checks{margin:12px 0;padding:10px;display:flex;gap:20px;border-radius:8px;background:#f5f7f8}.checks label{display:flex;align-items:center;gap:6px}.checks input{width:auto;margin:0!important}.dialog>footer{display:flex;justify-content:flex-end;gap:6px}@media(max-width:850px){.hero{flex-wrap:wrap}.hero>b{margin-left:0}.cards,.grid{grid-template-columns:1fr}.wide{grid-column:auto}}
</style>
